(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   荧光图像智能判读 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  成像标准化：荧光图像（不同灯源）→ 亮度一致\n   屏 2  颜色特征 + 分类：标准化 → 颜色特征 → 含油级别\n   屏 3  抽查复核：判级给建议，人工抽查\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var LEVEL = ['无', '微', '弱', '中', '强'];\n    var LCOL = ['#d8d2c4', '#a9c6a3', '#d8b64a', '#e0a030', '#c98a2b'];\n\n    /* -----------------------------------------------------\n       合成荧光图像特征\n       每张图合成 { bright(平均亮度), hue(主色相), sat(饱和), area(发光面积), level(真值) }\n       level 越高 → 亮度/饱和/面积越大\n       light 0/1 = 两种灯源（亮度/色偏不同）\n       ----------------------------------------------------- */\n    function genFluor(n, seed, light) {\n      var rnd = mulberry32(seed || 20261181);\n      var imgs = [];\n      for (var i = 0; i < n; i++) {\n        /* 真值含油级别：偏向中低，强/微少（不均衡） */\n        var r = rnd();\n        var level = r < 0.3 ? 0 : r < 0.55 ? 1 : r < 0.78 ? 2 : r < 0.93 ? 3 : 4;\n        var base = 0.15 + level * 0.17;\n        var bright = clamp(base + (rnd() - 0.5) * 0.17, 0.05, 0.95);\n        var hue = 0.12 + level * 0.02 + (rnd() - 0.5) * 0.02;   /* 黄→橙 */\n        var sat = clamp(0.2 + level * 0.15 + (rnd() - 0.5) * 0.24, 0.05, 0.95);\n        var area = clamp(0.1 + level * 0.17 + (rnd() - 0.5) * 0.22, 0.02, 0.95);\n        /* 灯源差异：light 0 暗/低饱和，light 1 亮/高饱和 */\n        var lamp = light === 0 ? { b: 0.7, s: 0.75 } : { b: 1.0, s: 1.05 };\n        imgs.push({\n          bright: clamp(bright * lamp.b, 0.02, 1),\n          hue: hue,\n          sat: clamp(sat * lamp.s, 0.02, 1),\n          area: area,\n          light: light, level: level\n        });\n      }\n      return { n: n, imgs: imgs };\n    }\n\n    /* -----------------------------------------------------\n       成像标准化\n       用灯源参数校正亮度/色偏。mode 0 不校正，1 校正。\n       返回 { imgs: [{bright,hue,sat,area,level}] }\n       ----------------------------------------------------- */\n    function stdImaging(d, mode) {\n      var out = [];\n      for (var i = 0; i < d.imgs.length; i++) {\n        var im = d.imgs[i];\n        if (mode === 0) { out.push({ bright: im.bright, hue: im.hue, sat: im.sat, area: im.area, level: im.level, light: im.light }); }\n        else {\n          var b = im.light === 0 ? im.bright / 0.7 : im.bright / 1.0;\n          var s = im.light === 0 ? im.sat / 0.75 : im.sat / 1.05;\n          out.push({ bright: clamp(b, 0, 1), hue: im.hue, sat: clamp(s, 0, 1), area: im.area, level: im.level, light: im.light });\n        }\n      }\n      return { n: d.n, imgs: out };\n    }\n\n    /* -----------------------------------------------------\n       颜色特征工程\n       mode 0 单特征（只亮度），1 多特征（亮度+饱和+面积）。\n       返回 { feats: [[...]], }\n       ----------------------------------------------------- */\n    function colorFeat(s, mode) {\n      var feats = [];\n      for (var i = 0; i < s.imgs.length; i++) {\n        var im = s.imgs[i];\n        if (mode === 0) feats.push([im.bright]);\n        else feats.push([im.bright, im.sat, im.area]);\n      }\n      return { feats: feats };\n    }\n\n    /* -----------------------------------------------------\n       含油级别分类\n       阈值判级。返回 { pred: [], acc, cm(混淆矩阵) }\n       ----------------------------------------------------- */\n    function fluorClassify(s, thr) {\n      var pred = [], acc = 0, n = s.imgs.length;\n      for (var i = 0; i < n; i++) {\n        var im = s.imgs[i];\n        var score = im.bright * 0.5 + im.sat * 0.3 + im.area * 0.2;\n        var p = score < thr[0] ? 0 : score < thr[1] ? 1 : score < thr[2] ? 2 : score < thr[3] ? 3 : 4;\n        pred.push(p);\n        if (p === im.level) acc++;\n      }\n      return { pred: pred, acc: n ? acc / n : 0, n: n };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, LEVEL: LEVEL, LCOL: LCOL,\n      genFluor: genFluor, stdImaging: stdImaging, colorFeat: colorFeat, fluorClassify: fluorClassify\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = { nImg: 240, stdMode: 1, featMode: 1, thr: [0.2, 0.38, 0.56, 0.74] };\n\n  var d = M.genFluor(state.nImg, 20261181, 0);\n\n  global.RemoteBridge = {\n    M: M,\n    genFluor: M.genFluor, stdImaging: M.stdImaging, colorFeat: M.colorFeat, fluorClassify: M.fluorClassify,\n    live: function () {\n      return { nImg: state.nImg, stdMode: state.stdMode, featMode: state.featMode, thr: state.thr };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 2 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* ---------- 屏 1 渲染：成像标准化 ---------- */\n  function renderStd() {\n    d = M.genFluor(state.nImg, 20261181, 0);\n    var s = M.stdImaging(d, state.stdMode);\n    var std = M.stdImaging(M.genFluor(state.nImg, 20261181, 1), state.stdMode);\n    var s2 = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s2 += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">成像标准化：' + (state.stdMode === 0 ? '灯源未校正（亮度差大）' : '已校正（亮度一致）') + '<\/text>';\n    /* 两灯源亮度分布对比 */\n    s2 += '<text x=\"40\" y=\"42\" font-size=\"8.5\" fill=\"#79828a\">灯源A（暗）<\/text>';\n    var nBin = 10, bw2 = w / nBin;\n    var bins0 = new Array(nBin).fill(0), bins1 = new Array(nBin).fill(0);\n    var sLight0 = M.stdImaging(M.genFluor(120, 20261181, 0), state.stdMode);\n    var sLight1 = M.stdImaging(M.genFluor(120, 20261181, 1), state.stdMode);\n    for (var i = 0; i < sLight0.imgs.length; i++) {\n      var b0 = Math.min(nBin - 1, Math.floor(sLight0.imgs[i].bright * nBin));\n      bins0[b0]++;\n      var b1 = Math.min(nBin - 1, Math.floor(sLight1.imgs[i].bright * nBin));\n      bins1[b1]++;\n    }\n    var maxC = 1;\n    for (i = 0; i < nBin; i++) maxC = Math.max(maxC, bins0[i], bins1[i]);\n    var yC = 100, hC = 70;\n    for (i = 0; i < nBin; i++) {\n      var h0 = bins0[i] / maxC * hC;\n      var h1 = bins1[i] / maxC * hC;\n      s2 += '<rect x=\"' + (x0 + i * bw2) + '\" y=\"' + (yC - h0) + '\" width=\"' + (bw2 / 2 - 1) + '\" height=\"' + h0 + '\" fill=\"#41699b\"/>';\n      s2 += '<rect x=\"' + (x0 + i * bw2 + bw2 / 2) + '\" y=\"' + (yC - h1) + '\" width=\"' + (bw2 / 2 - 1) + '\" height=\"' + h1 + '\" fill=\"#b26a39\"/>';\n    }\n    s2 += '<text x=\"' + (x0 + 6) + '\" y=\"' + (yC + 14) + '\" font-size=\"7.5\" fill=\"#41699b\">灯源A<\/text>';\n    s2 += '<text x=\"' + (x0 + 66) + '\" y=\"' + (yC + 14) + '\" font-size=\"7.5\" fill=\"#b26a39\">灯源B<\/text>';\n    s2 += '<text x=\"' + (x0 + 6) + '\" y=\"' + (yC + hC + 24) + '\" font-size=\"7.5\" fill=\"#79828a\">亮度分布（标准化后两灯源应重合）<\/text>';\n    $('stdChart').innerHTML = s2;\n    $('roStd').textContent = state.stdMode === 0 ? '未校正' : '已校正';\n    $('roDiff').textContent = state.stdMode === 0 ? '灯源差大' : '灯源一致';\n  }\n\n  /* ---------- 屏 2 渲染：颜色特征 + 分类 ---------- */\n  function renderFeat() {\n    d = M.genFluor(state.nImg, 20261181, 0);\n    var s = M.stdImaging(d, state.stdMode);\n    var cf = M.colorFeat(s, state.featMode);\n    var cls = M.fluorClassify(s, state.thr);\n    var s2 = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s2 += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">颜色特征 + 分类：含油级别 ' + Math.round(cls.acc * 100) + '% 判对<\/text>';\n    /* 每张图按 level 与 pred 在二维散点（亮度 × 面积） */\n    var px = x0 + 10, py = y0 + 12, pw = 150, ph = 76;\n    s2 += '<line x1=\"' + px + '\" y1=\"' + (py + ph) + '\" x2=\"' + (px + pw) + '\" y2=\"' + (py + ph) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s2 += '<line x1=\"' + px + '\" y1=\"' + py + '\" x2=\"' + px + '\" y2=\"' + (py + ph) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s2 += '<text x=\"' + (px - 4) + '\" y=\"' + (py + 8) + '\" font-size=\"7\" fill=\"#79828a\">面积<\/text>';\n    s2 += '<text x=\"' + (px + pw / 2) + '\" y=\"' + (py + ph + 16) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#79828a\">亮度<\/text>';\n    for (var i = 0; i < s.imgs.length; i++) {\n      var im = s.imgs[i];\n      var sx = px + im.bright * pw;\n      var sy = py + ph - im.area * ph;\n      var col = cls.pred[i] === im.level ? M.LCOL[im.level] : '#d0a3a3';\n      s2 += '<circle cx=\"' + sx.toFixed(1) + '\" cy=\"' + sy.toFixed(1) + '\" r=\"2\" fill=\"' + col + '\" stroke=\"' + (cls.pred[i] === im.level ? 'none' : '#b05a51') + '\" stroke-width=\"0.6\"/>';\n    }\n    s2 += '<text x=\"' + (px + pw + 8) + '\" y=\"' + (py + 12) + '\" font-size=\"7.5\" fill=\"#4d565b\">点色=级别<\/text>';\n    s2 += '<text x=\"' + (px + pw + 8) + '\" y=\"' + (py + 24) + '\" font-size=\"7.5\" fill=\"#b05a51\">红圈=判错<\/text>';\n    /* 右侧：级别柱（真值 vs 判级） */\n    var rx = x0 + 172, rw = 120, rh = 76, ry = py;\n    var bins = new Array(5).fill(0), binsP = new Array(5).fill(0);\n    for (i = 0; i < s.imgs.length; i++) { bins[s.imgs[i].level]++; binsP[cls.pred[i]]++; }\n    var maxB = 1;\n    for (i = 0; i < 5; i++) maxB = Math.max(maxB, bins[i]);\n    for (i = 0; i < 5; i++) {\n      var hh = bins[i] / maxB * rh;\n      s2 += '<rect x=\"' + (rx + i * (rw / 5)) + '\" y=\"' + (ry + rh - hh) + '\" width=\"' + (rw / 5 - 3) + '\" height=\"' + hh + '\" fill=\"' + M.LCOL[i] + '\"/>';\n    }\n    s2 += '<text x=\"' + (rx + rw / 2) + '\" y=\"' + (ry + rh + 16) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#79828a\">级别分布（真值）<\/text>';\n    $('featChart').innerHTML = s2;\n    $('roAcc').textContent = Math.round(cls.acc * 100) + '%';\n    $('roFeat').textContent = state.featMode === 0 ? '单特征' : '多特征';\n  }\n\n  /* ---------- 屏 3 渲染：抽查复核 ---------- */\n  function renderRev() {\n    d = M.genFluor(state.nImg, 20261181, 0);\n    var s = M.stdImaging(d, state.stdMode);\n    var cls = M.fluorClassify(s, state.thr);\n    var s2 = '';\n    var x0 = 40, y0 = 40, w = 300, h = 80;\n    /* 复核清单：挑判错/低置信样本 */\n    s2 += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">抽查复核：判级给建议 · 复核 ' + (cls.n - (function () { var c = 0; for (var i = 0; i < cls.pred.length; i++) if (cls.pred[i] !== s.imgs[i].level) c++; return c; })()) + '/' + cls.n + ' 已判对<\/text>';\n    var items = [];\n    for (var i = 0; i < s.imgs.length; i++) {\n      if (cls.pred[i] !== s.imgs[i].level) {\n        items.push({ idx: i, level: s.imgs[i].level, pred: cls.pred[i], bright: s.imgs[i].bright });\n      }\n    }\n    /* 前面几张判错的 */\n    var shown = items.slice(0, 5);\n    var x = x0, y = y0 + 12;\n    for (var k = 0; k < shown.length; k++) {\n      var it = shown[k];\n      var rowY = y + k * 34;\n      s2 += '<rect x=\"' + x + '\" y=\"' + rowY + '\" width=\"' + w + '\" height=\"28\" rx=\"5\" fill=\"#f9efea\" stroke=\"#e0c3a8\"/>';\n      s2 += '<text x=\"' + (x + 8) + '\" y=\"' + (rowY + 18) + '\" font-size=\"8\" fill=\"#4d565b\">样' + it.idx + '<\/text>';\n      s2 += '<text x=\"' + (x + 44) + '\" y=\"' + (rowY + 18) + '\" font-size=\"8\" fill=\"#8a4f27\">真' + M.LEVEL[it.level] + '<\/text>';\n      s2 += '<text x=\"' + (x + 90) + '\" y=\"' + (rowY + 18) + '\" font-size=\"8\" fill=\"#b05a51\">判' + M.LEVEL[it.pred] + '<\/text>';\n      s2 += '<text x=\"' + (x + 140) + '\" y=\"' + (rowY + 18) + '\" font-size=\"8\" fill=\"#2f7d6b\">待复核<\/text>';\n      var barW = 90;\n      s2 += '<rect x=\"' + (x + w - barW - 10) + '\" y=\"' + (rowY + 10) + '\" width=\"' + barW + '\" height=\"9\" rx=\"4\" fill=\"#f0ece2\"/>';\n      s2 += '<rect x=\"' + (x + w - barW - 10) + '\" y=\"' + (rowY + 10) + '\" width=\"' + (barW * it.bright) + '\" height=\"9\" rx=\"4\" fill=\"#c98a2b\"/>';\n    }\n    $('revChart').innerHTML = s2;\n    $('roRev').textContent = '待复核 ' + items.length + ' 张';\n    $('roOk').textContent = Math.round(cls.acc * 100) + '%';\n    /* 复核清单 */\n    var rows = [\n      ['成像标准化', state.stdMode === 0 ? '未校正' : '已校正', 'ok'],\n      ['含油级别', Math.round(cls.acc * 100) + '%', 'ok'],\n      ['抽查复核', items.length + ' 张待复核', 'ok']\n    ];\n    var rs = '';\n    for (var r = 0; r < rows.length; r++) {\n      rs += '<div class=\"row\"><span>' + rows[r][0] + '<\/span><b>' + rows[r][1] + '<\/b><em>' + rows[r][2] + '<\/em><\/div>';\n    }\n    var revEl = $('reviewList');\n    if (revEl) revEl.innerHTML = rs;\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inStd = $('inStd');\n    if (inStd) inStd.addEventListener('input', function () {\n      state.stdMode = parseInt(inStd.value, 10);\n      $('outStd').textContent = state.stdMode === 0 ? '未校正' : '已校正';\n      renderStd(); renderFeat(); renderRev();\n    });\n    var inFeat = $('inFeat');\n    if (inFeat) inFeat.addEventListener('input', function () {\n      state.featMode = parseInt(inFeat.value, 10);\n      $('outFeat').textContent = state.featMode === 0 ? '单特征' : '多特征';\n      renderFeat(); renderRev();\n    });\n    var inThr = $('inThr');\n    if (inThr) inThr.addEventListener('input', function () {\n      var v = parseFloat(inThr.value);\n      var dlt = 0.04;\n      state.thr = [v - 3 * dlt, v - dlt, v + dlt, v + 3 * dlt];\n      $('outThr').textContent = num(v, 2);\n      renderFeat(); renderRev();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '成像标准化', 'stdCtl'], ['sec2', '颜色特征+分类', 'featCtl'], ['sec3', '抽查复核', 'revCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderStd(); renderFeat(); renderRev();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   荧光图像智能判读 · 算法解剖（成像标准化 + 颜色特征 + 分类）\n   ---------------------------------------------------------\n   把「荧光图像 → 含油级别」拆成 6 步，每一步都跑真代码：\n\n     ① 荧光图像接入  固定灯源曝光\n     ② 成像标准化    灯源校正，亮度一致\n     ③ 颜色特征      颜色/面积量化级别\n     ④ 图像分类      自动判含油级别\n     ⑤ 抽查复核      判级给建议\n     ⑥ 回流          复核回流更准\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 240;\n  var C0 = '#41699b', C1 = '#b26a39', C2 = '#2f7d6b';\n\n  function footBox(x, w2, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w2, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nImg, L.stdMode, L.featMode, L.thr.join(',')].join(',');\n    if (cache.key === key) return cache;\n    var d = M.genFluor(N, 20261181, 0);\n    var s = M.stdImaging(d, L.stdMode);\n    var cf = M.colorFeat(s, L.featMode);\n    var cls = M.fluorClassify(s, L.thr);\n    cache = { key: key, L: L, d: d, s: s, cf: cf, cls: cls };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 荧光图像接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), d = c.d;\n    var s = '';\n    s += G.panel(0, '① 紫外荧光图像', '单井200—600张', C.blue);\n    s += G.panel(1, '② 灯源曝光', '固定参数', C.clay);\n    s += G.panel(2, '③ 含油级别标签', '无/微/弱/中/强', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '荧光图像（亮度按灯源显示）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var nBin = 10, x0 = G.COLS[0].x + 14, w2 = 240, hC = 90;\n    var bins = new Array(nBin).fill(0);\n    for (var i = 0; i < d.imgs.length; i++) {\n      var b = Math.min(nBin - 1, Math.floor(d.imgs[i].bright * nBin));\n      bins[b]++;\n    }\n    var maxC = 1;\n    for (i = 0; i < nBin; i++) maxC = Math.max(maxC, bins[i]);\n    for (i = 0; i < nBin; i++) {\n      var hh = bins[i] / maxC * hC;\n      s += G.rect(x0 + i * (w2 / nBin), y0 + hC - hh, w2 / nBin - 2, hh, { r: 2, fill: C0 });\n    }\n    s += G.line(x0, y0 + hC, x0 + w2, y0 + hC, { stroke: C.line, sw: 1 });\n    s += G.txt(x0 + 6, y0 + hC + 18, '单井200—600张 · 亮度直方图', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, y0, 170, '数据形态',\n      ['· 紫外荧光图像',\n       '· 固定灯源曝光',\n       '· 含油级别标签',\n       '',\n       '不固定灯源曝光，',\n       '亮度差异大，特征',\n       '不可比。'], 'clay');\n    return { svg: s, stats: [{ k: '图像', v: d.n + ' 张' }, { k: '级别', v: '5 级' }], note: '读入紫外荧光图像，固定灯源与曝光。不固定灯源与曝光，不同图像亮度差异大，特征不可比。' };\n  }\n\n  /* =========================================================\n     ② 成像标准化\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 原始图像', '亮度差异大', C.blue);\n    s += G.panel(1, '② 成像标准化', '灯源校正', C.jade);\n    s += G.panel(2, '③ 亮度一致', '特征可比', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '标准化后两灯源亮度分布', { size: 9.5, fill: C.ink2, weight: 700 });\n    var nBin = 10, x0 = G.COLS[0].x + 14, w2 = 240, hC = 90;\n    var sl0 = M.stdImaging(M.genFluor(120, 20261181, 0), L.stdMode);\n    var sl1 = M.stdImaging(M.genFluor(120, 20261181, 1), L.stdMode);\n    var b0 = new Array(nBin).fill(0), b1 = new Array(nBin).fill(0);\n    for (var i = 0; i < sl0.imgs.length; i++) { b0[Math.min(nBin - 1, Math.floor(sl0.imgs[i].bright * nBin))]++; }\n    for (i = 0; i < sl1.imgs.length; i++) { b1[Math.min(nBin - 1, Math.floor(sl1.imgs[i].bright * nBin))]++; }\n    var maxC = 1;\n    for (i = 0; i < nBin; i++) maxC = Math.max(maxC, b0[i], b1[i]);\n    for (i = 0; i < nBin; i++) {\n      var h0 = b0[i] / maxC * hC, h1 = b1[i] / maxC * hC;\n      s += G.rect(x0 + i * (w2 / nBin), y0 + hC - h0, w2 / nBin / 2 - 1, h0, { r: 2, fill: C0 });\n      s += G.rect(x0 + i * (w2 / nBin) + w2 / nBin / 2, y0 + hC - h1, w2 / nBin / 2 - 1, h1, { r: 2, fill: C1 });\n    }\n    s += G.line(x0, y0 + hC, x0 + w2, y0 + hC, { stroke: C.line, sw: 1 });\n    s += G.txt(x0 + 6, y0 + hC + 18, (L.stdMode === 0 ? '两灯源差异大' : '两灯源重合=亮度一致'), { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, y0, 170, '成像标准化的坑',\n      ['· 不做标准化',\n       '  → 灯源差异被当含油差异',\n       '· 误判',\n       '',\n       '用灯源记录校正',\n       '亮度色偏。'], 'jade');\n    return { svg: s, stats: [{ k: '标准化', v: L.stdMode === 0 ? '未' : '已' }, { k: '灯源', v: L.stdMode === 1 ? '一致' : '有差' }], note: '用灯源记录校正亮度与色偏，让不同灯源结论一致。不做标准化，灯源差异被当成含油级别差异，误判。' };\n  }\n\n  /* =========================================================\n     ③ 颜色特征工程\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), s = c.s, L = c.L;\n    var s2 = '';\n    s2 += G.panel(0, '① 标准化图像', '亮度一致', C.blue);\n    s2 += G.panel(1, '② 颜色特征', '颜色/面积', C.jade);\n    s2 += G.panel(2, '③ 级别量化', '可分类', C.clay);\n\n    var y0 = 130, h = 110;\n    s2 += G.txt(G.COLS[0].x + 14, y0 - 22, '颜色特征维度（' + (L.featMode === 0 ? '单特征' : '多特征') + '）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var x0 = G.COLS[0].x + 14, w2 = 240;\n    var dims = L.featMode === 0 ? [['亮度', C0]] : [['亮度', C0], ['饱和', C1], ['面积', C2]];\n    var dimW = (w2 - 10) / dims.length;\n    for (var k = 0; k < dims.length; k++) {\n      var dx = x0 + k * (dimW + 5);\n      s2 += G.rect(dx, y0, dimW, h, { r: 6, fill: C.blueL, stroke: dims[k][1], sw: 1.2 });\n      s2 += G.txt(dx + 6, y0 + 18, dims[k][0], { size: 9, fill: C.ink2, weight: 700 });\n      var sum = 0;\n      for (var i = 0; i < s.imgs.length; i++) sum += k === 0 ? s.imgs[i].bright : k === 1 ? s.imgs[i].sat : s.imgs[i].area;\n      var avg = sum / s.imgs.length;\n      var barH = 50;\n      s2 += G.rect(dx + 8, y0 + h - 24, dimW - 16, barH * avg, { r: 3, fill: dims[k][1] });\n      s2 += G.txt(dx + 6, y0 + h - 32, '均值 ' + f(avg), { size: 8, fill: C.ink3 });\n    }\n    s2 += G.txt(G.COLS[0].x + 14, y0 + h + 22, '多特征联合 → 边界模糊也分得开', { size: 8.5, fill: C.ink3 });\n\n    s2 += footBox(G.COLS[2].x + 14, y0, 170, '颜色特征的坑',\n      ['· 只取单一特征',\n       '  → 微弱/中强边界分不开',\n       '· 误判边界样本',\n       '',\n       '亮度+饱和+面积',\n       '联合量化级别。'], 'clay');\n    return { svg: s2, stats: [{ k: '特征', v: L.featMode === 0 ? '单' : '多' }, { k: '维度', v: L.featMode === 0 ? '1' : '3' }], note: '提取荧光颜色/面积特征，量化含油级别。只取单一颜色特征，微/弱、中/强边界模糊时分不开。' };\n  }\n\n  /* =========================================================\n     ④ 图像分类\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), s = c.s, cls = c.cls;\n    var s2 = '';\n    s2 += G.panel(0, '① 颜色特征', '颜色+面积', C.blue);\n    s2 += G.panel(1, '② 图像分类', '自动判级', C.jade);\n    s2 += G.panel(2, '③ 含油级别', '无/微/弱/中/强', C.clay);\n\n    var y0 = 130, h = 110;\n    s2 += G.txt(G.COLS[0].x + 14, y0 - 22, '含油级别分类 · 准确 ' + Math.round(cls.acc * 100) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n    var cm = new Array(5);\n    for (var a = 0; a < 5; a++) { cm[a] = new Array(5).fill(0); }\n    for (var i = 0; i < s.imgs.length; i++) { cm[s.imgs[i].level][cls.pred[i]]++; }\n    var cell = 30, mx = G.COLS[0].x + 14, my = y0;\n    for (var r = 0; r < 5; r++) {\n      for (var c2 = 0; c2 < 5; c2++) {\n        var v = cm[r][c2];\n        var alpha = v === 0 ? 0.08 : 0.2 + 0.8 * (v / Math.max(1, cm[r][r]));\n        s2 += G.rect(mx + c2 * cell, my + r * cell, cell - 2, cell - 2, { r: 3, fill: r === c2 ? C2 : '#f0a24c', op: alpha });\n        if (v > 0) s2 += G.txt(mx + c2 * cell + cell / 2, my + r * cell + cell / 2 + 4, String(v), { size: 8, fill: r === c2 ? '#fff' : C.ink, anchor: 'middle', weight: 700 });\n      }\n    }\n    s2 += G.txt(mx - 4, my - 6, '真值', { size: 7.5, fill: C.ink3 });\n    s2 += G.txt(mx, my + 5 * cell + 14, '预测 →', { size: 7.5, fill: C.ink3 });\n    s2 += G.txt(mx + 5 * cell + 8, my + 4, '对角=判对', { size: 8, fill: C.jadeD, weight: 700 });\n    s2 += G.txt(mx + 5 * cell + 8, my + 18, '非对角=误判', { size: 8, fill: '#8a4f27' });\n\n    s2 += footBox(G.COLS[2].x + 14, y0, 170, '图像分类的坑',\n      ['· 样本不均衡',\n       '  → 全猜多数类',\n       '· 稀有级别全漏',\n       '',\n       '特征充分 + 均衡处理',\n       '稀有级别不漏。'], 'jade');\n    return { svg: s2, stats: [{ k: '准确', v: Math.round(cls.acc * 100) + '%' }, { k: '样本', v: s.imgs.length + ' 张' }], note: '据颜色/面积特征自动判含油级别。样本不均衡时全猜多数类，稀有级别全漏。' };\n  }\n\n  /* =========================================================\n     ⑤ 抽查复核\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), s = c.s, cls = c.cls;\n    var s2 = '';\n    s2 += G.panel(0, '① 含油级别', '模型建议', C.blue);\n    s2 += G.panel(1, '② 抽查复核', '分级确认', C.clay);\n    s2 += G.panel(2, '③ 一致性↑', '不漏显示', C.jade);\n\n    var y0 = 130, h = 110;\n    s2 += G.txt(G.COLS[0].x + 14, y0 - 22, '抽查复核清单（判错/低置信样本）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var items = [];\n    for (var i = 0; i < s.imgs.length; i++) {\n      if (cls.pred[i] !== s.imgs[i].level) items.push({ idx: i, level: s.imgs[i].level, pred: cls.pred[i], bright: s.imgs[i].bright });\n    }\n    var shown = items.slice(0, 4);\n    var x0 = G.COLS[0].x + 14, w2 = 240;\n    for (var k = 0; k < shown.length; k++) {\n      var it = shown[k], rowY = y0 + k * 26;\n      s2 += G.rect(x0, rowY, w2, 22, { r: 4, fill: C.clayL, stroke: '#e6cdb2' });\n      s2 += G.txt(x0 + 6, rowY + 15, '样' + it.idx, { size: 8, fill: C.ink2 });\n      s2 += G.txt(x0 + 40, rowY + 15, '真' + M.LEVEL[it.level], { size: 8, fill: '#8a4f27', weight: 700 });\n      s2 += G.txt(x0 + 82, rowY + 15, '判' + M.LEVEL[it.pred], { size: 8, fill: '#b05a51', weight: 700 });\n      s2 += G.txt(x0 + 124, rowY + 15, '待复核', { size: 8, fill: C.jadeD });\n    }\n    s2 += G.txt(x0, y0 + h + 22, '共 ' + items.length + ' 张待复核', { size: 8.5, fill: C.ink3 });\n\n    s2 += footBox(G.COLS[2].x + 14, y0, 170, '抽查复核的坑',\n      ['· 复核不回流',\n       '  → 模型不知判错在哪',\n       '· 永远误判',\n       '',\n       '复核结果要回流，',\n       '判级越用越准。'], 'clay');\n    return { svg: s2, stats: [{ k: '待复核', v: items.length + ' 张' }, { k: '判对', v: Math.round(cls.acc * 100) + '%' }], note: '模型判级给建议，录井工只抽查复核。复核结果不回流，模型不知道判错在哪，永远误判。' };\n  }\n\n  /* =========================================================\n     ⑥ 回流\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), cls = c.cls;\n    var s = '';\n    s += G.panel(0, '① 判级建议', '模型输出', C.blue);\n    s += G.panel(1, '② 复核回流', '确认修正', C.clay);\n    s += G.panel(2, '③ 越用越准', '回流闭环', C.jade);\n\n    var y0 = 130, h = 110;\n    var rows = [\n      ['判级建议', '模型', '复核'],\n      ['复核确认', '人工', '修正'],\n      ['结果回流', '已回流', 'ok']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 38;\n      s += G.rect(G.COLS[0].x + 14, ry, 240, 30, { r: 5, fill: C.jadeL, stroke: '#b9d8cb' });\n      s += G.txt(G.COLS[0].x + 26, ry + 20, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(G.COLS[0].x + 140, ry + 20, rows[r][1], { size: 8.8, fill: C.jadeD });\n    }\n    s += G.txt(G.COLS[0].x + 14, y0 - 20, '回流闭环', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(G.COLS[2].x + 14, y0, 170, '回流的坑',\n      ['· 不回流',\n       '  → 数据不增，一直误判',\n       '· 无法越用越准',\n       '',\n       '复核+岩心描述回流，',\n       '模型持续变准。'], 'jade');\n    return { svg: s, stats: [{ k: '判对', v: Math.round(cls.acc * 100) + '%' }, { k: '回流', v: '已闭环' }], note: '复核结果回流训练集，模型越用越准、漏显示持续下降。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：荧光图像智能判读<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n.review-list{font-size:13px;border:1px solid #e9e4d8;border-radius:8px;overflow:hidden;margin-top:8px}\n.review-list .row{display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #f0ece2}\n.review-list .row:last-child{border-bottom:none}\n.review-list .row span{flex:1;color:#4d565b}\n.review-list .row b{width:220px;color:#24333a;font-weight:700}\n.review-list .row em{color:#2f7d6b;font-style:normal;font-weight:700;font-size:12px}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 录井 / 荧光图像智能判读<\/span>\n  <h1>从「目估分级」到「成像标准化 + 颜色特征 + 图像分类」<\/h1>\n  <p class=\"sub\">三个实验：Q1 成像标准化、Q2 颜色特征+分类、Q3 抽查复核。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 判读全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「荧光图像 → 黑盒 → 含油级别」，而是<b>逐段展开<\/b>：图像接入 → 成像标准化 → 颜色特征 → 图像分类 → 抽查复核 → 回流，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 1—6<\/span>\n    <h2>把「荧光图像 → 含油级别」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。切成像标准化、颜色特征，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（亮度一致、含油级别、待复核清单）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>stdImaging / colorFeat / fluorClassify<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步把两灯源亮度分布并列，看得见成像标准化把差异拉平；<b>②<\/b> 第 4 步用混淆矩阵展示判级，看得见「对多少、错多少、错到哪」。 <\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 成像标准化 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">荧光判读靠目估分级，主观性强；灯源差异大时结论差异大<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 1—2<\/span>\n    <h2>成像标准化：不同灯源 → 亮度一致<\/h2>\n    <p class=\"leadline\">切未校正/已校正，看两灯源亮度分布怎么重合。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"stdCtl\">\n    <div class=\"sl\">\n      <label>成像标准化<output id=\"outStd\">已校正<\/output><\/label>\n      <input type=\"range\" id=\"inStd\" min=\"0\" max=\"1\" step=\"1\" value=\"1\">\n    <\/div>\n  <\/div>\n  <svg id=\"stdChart\" viewBox=\"0 0 400 180\" role=\"img\" aria-label=\"成像标准化\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">标准化<\/span><b id=\"roStd\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">灯源<\/span><b id=\"roDiff\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"stdTip\">荧光录井用紫外灯照射岩屑/岩心，不同灯源、曝光下结论差异大。成像标准化校正亮度与色偏，让不同灯源结论一致，特征可比。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 颜色特征 + 分类 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>图像分类<\/b>：标准化图像 → 颜色特征 → 含油级别<span class=\"qa-algo\">颜色特征工程 · 图像分类<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3—4<\/span>\n    <h2>颜色特征 + 分类：标准化 → 含油级别<\/h2>\n    <p class=\"leadline\">切单/多特征、拖阈值，看判级怎么变。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"featCtl\">\n    <div class=\"sl\">\n      <label>颜色特征<output id=\"outFeat\">多特征<\/output><\/label>\n      <input type=\"range\" id=\"inFeat\" min=\"0\" max=\"1\" step=\"1\" value=\"1\">\n    <\/div>\n    <div class=\"sl\">\n      <label>判级阈值<output id=\"outThr\">0.38<\/output><\/label>\n      <input type=\"range\" id=\"inThr\" min=\"0.2\" max=\"0.56\" step=\"0.01\" value=\"0.38\">\n    <\/div>\n  <\/div>\n  <svg id=\"featChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"颜色特征与分类\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">级别准确<\/span><b id=\"roAcc\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">特征<\/span><b id=\"roFeat\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"featTip\">荧光图像按含油级别分级标注（无/微/弱/中/强）。颜色特征工程提取亮度/饱和/面积量化级别，图像分类自动判级；单特征在微/弱、中/强边界分不开，多特征联合更稳。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 抽查复核 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">判级给建议 → <b>抽查复核<\/b>（录井工只复核，不漏显示）<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5—6<\/span>\n    <h2>抽查复核：判级给建议 + 复核回流<\/h2>\n    <p class=\"leadline\">看待复核清单、判对率与复核回流。<\/p>\n  <\/div>\n  <svg id=\"revChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"抽查复核\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">待复核<\/span><b id=\"roRev\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">判对率<\/span><b id=\"roOk\">—<\/b><\/div>\n  <\/div>\n  <div class=\"review-list\" id=\"reviewList\"><\/div>\n  <p class=\"tip\" id=\"revTip\">荧光判读目估分级主观，漏显示会错失油气显示。图像分类自动判级给建议，录井工只抽查复核判错/低置信样本；复核结果回流，判级越用越准、不漏显示。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 1—2<\/b><br>成像标准化。<\/div>\n    <div><b>实验 2 → STEP 3—4<\/b><br>颜色特征+分类。<\/div>\n    <div><b>实验 3 → STEP 5—6<\/b><br>抽查复核 + 回流。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：荧光图像由「含油级别基础 + 灯源差异 + 噪声」合成，真实级别已知、仅供对比；成像标准化、颜色特征与含油级别分类均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：荧光图像怎么一步步变成含油级别',\n    stages: [\n      { name: '图像接入', tag: '荧光图', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '成像标准化', tag: '亮度一致', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: '颜色特征', tag: '级别量化', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '图像分类', tag: '自动判级', dur: 4600, draw: function (t, g) { return F.stage4(t); } },\n      { name: '抽查复核', tag: '判错样本', dur: 4200, draw: function (t, g) { return F.stage5(t); } },\n      { name: '回流', tag: '更准', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的荧光图像演示成像标准化、颜色特征与含油级别分类。","height":600};
  var META = {"id":"m3-fluor-image","sceneId":"m3","title":"荧光图像智能判读：图像分类 + 颜色特征 + 成像标准化"};
  var handle = null;
  var DEF = {"id":"m3-fluor-image","sceneId":"m3","title":"荧光图像智能判读：图像分类 + 颜色特征 + 成像标准化","methods":["cv"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"紫外荧光图","desc":"单井200—600张"},{"label":"标注成本","value":"中","desc":"按含油级别"},{"label":"可见收益","value":"判读一致+不漏显示","desc":"替代目估"},{"label":"难度","value":"中","desc":"灯源差异大"}],"lede":"荧光录井用紫外灯照射岩屑/岩心，据荧光颜色与面积判断含油级别（无/微/弱/中/强），是发现油气显示的重要辅助。判读靠目估分级，主观性强；灯源差异大时结论差异也大。智能方法用图像分类自动判含油级别，做颜色特征工程与成像标准化。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p><b>荧光录井<\/b>用紫外灯照射岩屑/岩心，据荧光颜色与面积判断含油级别（无/微/弱/中/强），是发现油气显示的重要辅助。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>目估分级主观<\/b>——同一块样品不同人可差一个级别<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>灯源差异大<\/b>——不同灯源、曝光下结论差异大<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>量级大<\/b>——单井 200—600 张图，逐张目估费时<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工荧光判读的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">人工目估荧光 → 主观分级 · 灯源差异大<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">人工判读<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">荧光颜色目估<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">面积目估<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">主观分级<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">灯源差异大<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">结论差异大 → 漏显示<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">单井200—600张<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 目估分级主观<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 灯源差异大<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 图像量大<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">同一块样品可差一个级别<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">需要智能判读<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>用<b>图像分类<\/b>自动判含油级别，做<b>颜色特征工程<\/b>与<b>成像标准化<\/b>，替代目估分级。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>成像标准化<\/b>——校正灯源与曝光差异，让不同灯源结论一致<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>颜色特征工程<\/b>——提取荧光颜色/面积特征，量化含油级别<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>图像分类<\/b>——据特征自动判含油级别（无/微/弱/中/强）<\/span><\/div><\/div><p>落地形态：荧光图像自动判级，人工只做抽查复核。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"荧光智能判读流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">荧光图像 → 成像标准化 + 颜色特征 → 含油级别<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">荧光图像<\/text><path d=\"M40 78 C56 70 72 86 100 80\" fill=\"none\" stroke=\"#c98a2b\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">单井200—600张<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">成像标准化<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">灯源校正<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">曝光统一<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">颜色特征<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">颜色/面积<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">量化级别<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">含油级别<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">无/微/弱/中/强<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">抽查复核<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">自动判级 · 结论一致 · 不漏显示<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>紫外荧光图像<\/b>：固定紫外灯源与曝光，单井 200—600 张；<b>含油级别标签<\/b>：按无/微/弱/中/强分级标注；<b>灯源记录<\/b>：灯源型号与曝光参数，用于标准化。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"荧光判读数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">荧光智能判读需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">紫外荧光图像<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">固定灯源与曝光<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">单井200—600张<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">含油级别标签<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">无/微/弱/中/强<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">分级标注<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">灯源记录<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">灯源型号/曝光<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">用于标准化<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">岩心描述<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">含油性描述<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">交叉验证<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：成像标准化 + 颜色特征 + 图像分类<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>目估分级主观<\/b>——同一块样品不同人可差一个级别<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>灯源差异大<\/b>——不同灯源、曝光下结论差异大<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>边界模糊<\/b>——微/弱、中/强之间边界模糊<\/span><\/div><\/div><p>改进路线按成本从低到高：先做<b>成像标准化<\/b>统一灯源与曝光；再加<b>颜色特征工程<\/b>量化含油级别；最后用<b>图像分类<\/b>自动判级。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"荧光判读难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 目估分级主观<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">可差一个级别<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">成像标准化<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">统一灯源曝光<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 灯源差异大<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">结论差异大<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">颜色特征工程<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">量化含油级别<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 边界模糊<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">微弱中强<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">图像分类<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">自动判级<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">成像标准化 → 颜色特征 → 图像分类<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口井的荧光判读改造","lead":["某井此前由录井工目估荧光含油级别，主观分级、灯源差异大、结论不一致。目标：成像标准化统一灯源曝光，颜色特征量化含油级别，图像分类自动判级。","注意第 3、4、5 步：成像标准化、颜色特征、图像分类是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某生产井"],["图像规模","单井200—600张"],["判读方式","人工目估分级"],["灯源","紫外灯"],["目标","含油级别自动判"],["难点","主观+灯源差异"]],"steps":[{"name":"荧光图像接入","role":"数据","do":"读入紫外荧光图像，固定灯源与曝光。示范页屏 1 顶部可看荧光图像。","effect":"单井 200—600 张图像集，含油级别标签。","trap":"不固定灯源与曝光，不同图像亮度差异大，特征不可比。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">荧光图像接入：固定灯源曝光<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">紫外荧光图像<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">单井200—600张<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">灯源曝光<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">固定参数<\/text><path d=\"M360 72 L384 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">含油级别标签<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">无/微/弱/中/强<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不固定灯源曝光 → 亮度差异大 → 特征不可比<\/text><\/svg>"},{"name":"成像标准化","role":"算法核心","do":"用灯源记录校正亮度与色偏，让不同灯源结论一致。示范页屏 1 展示标准化前后。","effect":"不同灯源、曝光下的图像亮度一致，特征可比。","trap":"不做标准化，灯源差异被当成含油级别差异，误判。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">成像标准化：不同灯源 → 亮度一致<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">原始图像<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">亮度差异大<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">成像标准化<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">灯源校正<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">亮度一致<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">特征可比<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不做标准化 → 灯源差异被当含油差异 → 误判<\/text><\/svg>"},{"name":"颜色特征工程","role":"算法核心","do":"提取荧光颜色/面积特征，量化含油级别。示范页屏 2 展示特征。","effect":"含油级别被量化成特征，可被分类器使用。","trap":"只取单一颜色特征，微/弱、中/强边界模糊时分不开。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">颜色特征：荧光 → 颜色/面积<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">标准化图像<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">亮度一致<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">颜色特征<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">RGB/HSV<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">含油级别量化<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">颜色+面积<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：单一特征 → 边界模糊分不开<\/text><\/svg>"},{"name":"图像分类","role":"算法核心","do":"据颜色/面积特征自动判含油级别。示范页屏 2 展示分类。","effect":"含油级别自动判出，替代目估分级。","trap":"样本不均衡时全猜多数类，稀有级别全漏。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">图像分类：特征 → 含油级别<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">颜色特征<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">颜色+面积<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">图像分类<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">自动判级<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">含油级别<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">无/微/弱/中/强<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：样本不均衡 → 全猜多数类 → 稀有级别漏<\/text><\/svg>"},{"name":"抽查复核","role":"人工确认","do":"模型判级给建议，录井工只抽查复核。示范页屏 3 展示复核清单。","effect":"判级一致性提升，稀有显示不漏。","trap":"复核结果不回流，模型不知道判错在哪，永远误判。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">抽查复核：判级 → 录井工复核<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">含油级别<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">模型建议<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">抽查复核<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">分级确认<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">一致性↑<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">不漏显示<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：复核不回流 → 模型不知错 → 永远误判<\/text><\/svg>"}],"metrics":{"title":"怎么算「判读对了」","html":"<p>荧光判读用 <b>含油级别准确率<\/b>（判对级别比例）与 <b>邻级容差<\/b> 双重验收；<b>漏显示<\/b> 衡量把有显示判成无的比例。<\/p><p>最终还要看 <b>抽查复核<\/b>：复核结果回流后，判级是否越用越准。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='荧光判读效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>荧光判读验收：级别准确 × 邻级容差 × 漏显示<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>级别准确率<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>准确 58%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>人工目估<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>准确 91%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>图像分类<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>判级 ↑ 主观 ↓<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>邻级容差 + 漏显示<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>邻级容差↑<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>微/弱不误判<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>漏显示↓<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>有显示不漏<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>结论一致 · 不漏显示<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 级别准确 × 邻级容差 × 漏显示<\/text><\/svg><\/p>"},"fails":[{"name":"目估分级主观","why":"同一块样品不同人可差一个级别，判读一致性差。"},{"name":"灯源差异大","why":"不同灯源、曝光下结论差异大，不做标准化会误判。"},{"name":"边界模糊","why":"微/弱、中/强之间边界模糊，单一特征分不开。"},{"name":"样本不均衡","why":"稀有含油级别样本少，全猜多数类会漏稀有显示。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的荧光图像演示成像标准化、颜色特征与含油级别分类。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
